import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds exact half cents to the even cent so invoices don't drift upward", () => {
    expect(roundCents(2.5)).toBe(2);
    expect(roundCents(3.5)).toBe(4);
    expect(roundCents(-2.5)).toBe(-2);
    expect(roundCents(-3.5)).toBe(-4);
  });

  it("rounds non-half fractions to the nearest cent", () => {
    expect(roundCents(10.49)).toBe(10);
    expect(roundCents(10.51)).toBe(11);
    expect(roundCents(-10.51)).toBe(-11);
  });

  it("leaves whole-cent amounts unchanged", () => {
    expect(roundCents(1999)).toBe(1999);
  });
});

